class ProfilePayload(BaseModel):
    """PUT /me/profile — full replace."""

    model_config = ConfigDict(extra="forbid")

    birth_date: Optional[str] = Field(default=None, examples=["1974-02-24"])
    birth_time: Optional[str] = Field(default=None, examples=["05:30:00"])
    birth_location: Optional[str] = Field(default=None, examples=["seoul"])
    timezone_str: str = Field(default="Asia/Seoul")
    longitude: float = Field(default=126.9780)
    gender: str = Field(default="M")
    jasi_boundary: int = Field(default=23)
    correction_mode: str = Field(default="lmt")

    @field_validator("birth_date")
    @classmethod
    def v_birth_date(cls, v):
        if v is None:
            return v
        try:
            dt = datetime.strptime(v, "%Y-%m-%d")
            if not (1900 <= dt.year <= 2100):
                raise ValueError("연도는 1900년에서 2100년 사이여야 합니다.")
        except ValueError as e:
            if "연도는" in str(e):
                raise e
            raise ValueError("birth_date must be in YYYY-MM-DD format")
        return dt.strftime("%Y-%m-%d")

    @field_validator("birth_time")
    @classmethod
    def v_birth_time(cls, v):
        if v is None:
            return v
        for fmt in ("%H:%M:%S", "%H:%M"):
            try:
                dt = datetime.strptime(v, fmt)
                return dt.strftime("%H:%M:%S")
            except ValueError:
                continue
        raise ValueError("birth_time must be in HH:MM:SS or HH:MM format")

    @field_validator("longitude")
    @classmethod
    def v_longitude(cls, v):
        if not (-180.0 <= v <= 180.0):
            raise ValueError("Longitude must be between -180 and 180 degrees.")
        return v

    @field_validator("jasi_boundary")
    @classmethod
    def v_jasi(cls, v):
        if v not in (23, 0):
            raise ValueError("jasi_boundary must be 23 or 0.")
        return v

    @field_validator("correction_mode")
    @classmethod
    def v_correction(cls, v):
        m = v.lower()
        if m not in ("lmt", "none"):
            raise ValueError("correction_mode must be 'lmt' or 'none'.")
        return m

    @field_validator("gender")
    @classmethod
    def v_gender(cls, v):
        g = v.upper()
        if g not in ("M", "F", "남", "여"):
            raise ValueError("gender must be 'M' or 'F'.")
        return "M" if g in ("M", "남") else "F"


class PushTokenPayload(BaseModel):
    model_config = ConfigDict(extra="forbid")
    token: str = Field(..., min_length=1, max_length=512)
    platform: str = Field(..., examples=["ios", "android", "web"])
    device_id: Optional[str] = Field(default=None, max_length=128)

    @field_validator("platform")
    @classmethod
    def v_platform(cls, v: str) -> str:
        p = v.lower().strip()
        if p not in ("ios", "android", "web"):
            raise ValueError("platform must be one of: ios, android, web.")
        return p


